Can be implemented on top of the new `vec_order()` in C using the tracked group sizes

```r
library(vctrs)
library(rlang)

vec_rank <- function(x, 
                     ...,
                     ties = c("min", "max", "sequential", "dense"),
                     na_propagate = FALSE,
                     na_value = "largest",
                     nan_distinct = FALSE,
                     chr_transform = NULL) {
  if (!missing(...)) {
    ellipsis::check_dots_empty()
  }
  
  ties <- arg_match0(ties, c("min", "max", "sequential", "dense"), "ties")
  
  if (!is_bool(na_propagate)) {
    abort("`na_propagate` must be a boolean value.")
  }
  
  if (na_propagate) {
    fixup <- na_propagate_fixup(x, na_value)
    x <- fixup$x
    na_value <- fixup$na_value
  }
  
  info <- vctrs:::vec_order_info(
    x = x, 
    direction = "asc",
    na_value = na_value,
    nan_distinct = nan_distinct,
    chr_transform = chr_transform
  )
  
  order <- info[[1]]
  sizes <- info[[2]]
  
  out <- vector("integer", length = vec_size(x))
  
  out <- switch(
    ties,
    min = vec_rank_min(out, sizes, order),
    max = vec_rank_max(out, sizes, order),
    sequential = vec_rank_sequential(out, sizes, order),
    dense = vec_rank_dense(out, sizes, order)
  )
  
  if (na_propagate && fixup$any_missing) {
    out[fixup$missing] <- NA_integer_
  }
  
  out
}

na_propagate_fixup <- function(x, na_value) {
  missing <- vec_equal_na(x)
  any_missing <- any(missing)
  
  if (!any_missing) {
    out <- list(x = x, na_value = na_value, missing = missing, any_missing = any_missing)
    return(out)
  }
  
  x_is_data_frame <- is.data.frame(x)
  
  if (!is_character(na_value)) {
    abort("`na_value` must be a character vector.")
  }
  if (x_is_data_frame && length(na_value) == 1L) {
    na_value <- c("largest", rep(na_value, times = ncol(x)))
  } else {
    na_value <- c("largest", na_value)
  }
  
  if (x_is_data_frame) {
    x <- unclass(x)
    x <- data_frame(`vctrs:::missing` = missing, !!!x, .name_repair = "minimal")
  } else {
    x <- data_frame(`vctrs:::missing` = missing, x = x, .name_repair = "minimal")
  }
  
  list(x = x, na_value = na_value, missing = missing, any_missing = any_missing)
}

vec_rank_min <- function(out, sizes, order) {
  loc <- 1L
  rank <- 1L
  
  for (size in sizes) {
    for (i in seq_len(size)) {
      out_loc <- order[[loc]]
      out[[out_loc]] <- rank
      loc <- loc + 1L
    }
    rank <- rank + size
  }
  
  out
}

vec_rank_max <- function(out, sizes, order) {
  loc <- 1L
  rank <- 0L
  
  for (size in sizes) {
    rank <- rank + size
    
    for (i in seq_len(size)) {
      out_loc <- order[[loc]]
      out[[out_loc]] <- rank
      loc <- loc + 1L
    }
  }
  
  out
}

vec_rank_sequential <- function(out, sizes, order) {
  loc <- 1L
  rank <- 1L
  
  for (size in sizes) {
    for (i in seq_len(size)) {
      out_loc <- order[[loc]]
      out[[out_loc]] <- rank
      loc <- loc + 1L
      rank <- rank + 1L
    }
  }
  
  out
}

vec_rank_dense <- function(out, sizes, order) {
  loc <- 1L
  rank <- 1L
  
  for (size in sizes) {
    for (i in seq_len(size)) {
      out_loc <- order[[loc]]
      out[[out_loc]] <- rank
      loc <- loc + 1L
    }
    rank <- rank + 1L
  }
  
  out
}


# Already faster than `rank()`, but we can get much faster!
x <- sample(500, 1e6, T)

bench::mark(
  rank(x, ties.method = "min"),
  data.table::frank(x, ties.method = "min"),
  vec_rank(x)
)
