  data.table::frank(y, ties.method = "first", na.last = "keep"),
  vec_rank(y, na_propagate = TRUE, ties = "sequential")
)
#> Warning: Some expressions had a GC in every iteration; so filtering is disabled.
#> # A tibble: 3 x 6
#>   expression                                                         min  median
#>   <bch:expr>                                                    <bch:tm> <bch:t>
#> 1 rank(y, ties.method = "first", na.last = "keep")                32.8ms  40.4ms
#> 2 data.table::frank(y, ties.method = "first", na.last = "keep")   38.2ms  48.4ms
#> 3 vec_rank(y, na_propagate = TRUE, ties = "sequential")           73.1ms  83.8ms
#> # … with 3 more variables: itr/sec <dbl>, mem_alloc <bch:byt>, gc/sec <dbl>

df <- data.frame(x = c(2, 2, 2, NA, NA), y = c(1, 3, 1, NA, 1))
df
#>    x  y
#> 1  2  1
#> 2  2  3
#> 3  2  1
#> 4 NA NA
#> 5 NA  1

# `NA` values are largest, fully `NA` rows are "larger" than partially `NA` rows
vec_rank(df, na_value = "largest")
#> [1] 1 3 1 5 4

# `na_propagate = TRUE` makes fully missing rows propagate an `NA` value
# partially missing rows are still handled by `na_value`
vec_rank(df, na_value = "largest", na_propagate = TRUE)
#> [1]  1  3  1 NA  4

vec_rank(df, na_value = "smallest", na_propagate = TRUE)
#> [1]  2  4  2 NA  1

# Default ties method is `"min"`, but we also have:
# max, sequential == first, dense
vec_rank(df, ties = "max")
#> [1] 2 3 2 5 4
vec_rank(df, ties = "sequential")
#> [1] 1 3 2 5 4
vec_rank(df, ties = "dense")
#> [1] 1 2 1 4 3
```

Both `as_list_of.list()` and `as_list_of.vctrs_list_of()` call `list_of(!!!x, .ptype = .ptype)` which directly collects the input again via `list2()`. As profvis shows this roundtrip doubles to triples the time required

![image](https://user-images.githubusercontent.com/18258854/86111066-9be52c80-bac6-11ea-861e-f4850d2d8ec7.png)


```r
vctrs:::as_list_of.list <- function (x, ..., .ptype = NULL) {
    list_of(!!!x, .ptype = .ptype)
}

vctrs:::list_of <- function (..., .ptype = NULL) {
    args <- list2(...)
    ptype <- vec_ptype_common(!!!args, .ptype = .ptype)
    if (is.null(ptype)) {
        abort("Could not find common type for elements of `x`.")
    }
    x <- map(args, vec_cast, to = ptype)
    new_list_of(x, ptype)
}
```

I don't know if https://github.com/r-lib/rlang/issues/937 would help to speed this up but it would be great if one could avoid this performance loss which feels quite unnecessary.

