  bool cmp_str(Rcpp::CharacterVector c1) {
    static const Rcpp::String string_propagate = "propagate";
    static SEXP sexp_propagate = string_propagate.get_sexp();
    for (int i = 0; i < c1.length(); ++i) {
      if (c1[i] != sexp_propagate) return false;
