`vec_group_rle()` was implemented in #627 

If we ever require further performance improvements for this function (especially for the case where groups are already contiguous), target the `equal_scalar()` as the main potential for improvement. It could be replaced with the actual underlying `lgl_equal_scalar()`, `dbl_equal_scalar()`, etc, function using macros. 

Note that this would have nice improvements on atomic vectors, but the benefits might not be as good on data frames because `df_equal_scalar()` would still be calling `equal_scalar()` on each of the columns.

The implementation could be swapped for a cleaner version of something like this, which borrows from the `EQUAL` and `EQUAL_BARRIER` macros

<details>

```
#define RLE_EQUAL(CTYPE, CONST_DEREF, SCALAR_EQUAL)            \
  do {                                                         \
    const CTYPE* xp = CONST_DEREF(x);                          \
                                                               \
    for (int i = 1; i < n; ++i) {                              \
      if (SCALAR_EQUAL(xp + i - 1, xp + i, true)) {            \
        ++(*p_l);                                              \
        continue;                                              \
      }                                                        \
                                                               \
      ++p_l;                                                   \
      *p_l = 1;                                                \
                                                               \
      /* Check if we have seen this value before */            \
      int32_t hash = dict_hash_scalar(&d, i);                  \
                                                               \
      if (d.key[hash] == DICT_EMPTY) {                         \
        dict_put(&d, hash, i);                                 \
        p_map[hash] = pos;                                     \
        p_g[pos] = d.used;                                     \
      } else {                                                 \
        p_g[pos] = p_g[p_map[hash]];                           \
      }                                                        \
                                                               \
      ++pos;                                                   \
    }                                                          \
  }                                                            \
  while (0)

#define RLE_EQUAL_BARRIER(SCALAR_EQUAL)                        \
  do {                                                         \
    for (int i = 1; i < n; ++i) {                              \
      if (SCALAR_EQUAL(x, i - 1, x, i, true)) {                \
        ++(*p_l);                                              \
        continue;                                              \
      }                                                        \
                                                               \
      ++p_l;                                                   \
      *p_l = 1;                                                \
                                                               \
      /* Check if we have seen this value before */            \
      int32_t hash = dict_hash_scalar(&d, i);                  \
                                                               \
      if (d.key[hash] == DICT_EMPTY) {                         \
        dict_put(&d, hash, i);                                 \
        p_map[hash] = pos;                                     \
        p_g[pos] = d.used;                                     \
      } else {                                                 \
        p_g[pos] = p_g[p_map[hash]];                           \
      }                                                        \
                                                               \
      ++pos;                                                   \
    }                                                          \
  }                                                            \
  while (0)

SEXP vctrs_group_rle(SEXP x) {
  int nprot = 0;

  R_len_t n = vec_size(x);

  x = PROTECT_N(vec_proxy_recursive(x, vctrs_proxy_equal), &nprot);
  x = PROTECT_N(obj_maybe_translate_encoding(x, n), &nprot);

  enum vctrs_type type = vec_proxy_typeof(x);

  dictionary d;
  dict_init(&d, x);
  PROTECT_DICT(&d, &nprot);

  SEXP g = PROTECT_N(Rf_allocVector(INTSXP, n), &nprot);
  int* p_g = INTEGER(g);

  SEXP l = PROTECT_N(Rf_allocVector(INTSXP, n), &nprot);
  int* p_l = INTEGER(l);

  SEXP map = PROTECT_N(Rf_allocVector(INTSXP, d.size), &nprot);
  int* p_map = INTEGER(map);

  if (n == 0) {
    SEXP out = PROTECT_N(new_group_rle(g, l, 0), &nprot);
    UNPROTECT(nprot);
    return out;
  }

  // First value has not been seen
  int32_t hash = dict_hash_scalar(&d, 0);
  dict_put(&d, hash, 0);
  p_map[hash] = 0;

  *p_g = 1;
  *p_l = 1;

  int pos = 1;

  switch (type) {
  case vctrs_type_logical:   RLE_EQUAL(int, LOGICAL_RO, lgl_equal_scalar); break;
  case vctrs_type_integer:   RLE_EQUAL(int, INTEGER_RO, int_equal_scalar); break;
  case vctrs_type_double:    RLE_EQUAL(double, REAL_RO, dbl_equal_scalar); break;
  case vctrs_type_raw:       RLE_EQUAL(Rbyte, RAW_RO, raw_equal_scalar); break;
  case vctrs_type_complex:   RLE_EQUAL(Rcomplex, COMPLEX_RO, cpl_equal_scalar); break;
  case vctrs_type_character: RLE_EQUAL(SEXP, STRING_PTR_RO, chr_equal_scalar); break;
  case vctrs_type_list:      RLE_EQUAL_BARRIER(list_equal_scalar); break;
  case vctrs_type_dataframe: RLE_EQUAL_BARRIER(df_equal_scalar); break;
  case vctrs_type_scalar:    Rf_errorcall(R_NilValue, "Can't compare scalars with `vctrs_equal()`");
  default:                   Rf_error("Unimplemented type in `vctrs_equal()`");
  }

  g = PROTECT_N(Rf_lengthgets(g, pos), &nprot);
  l = PROTECT_N(Rf_lengthgets(l, pos), &nprot);

  SEXP out = new_group_rle(g, l, d.used);

  UNPROTECT(nprot);
  return out;
}
```

