I'm not sure if you were trying to support these yet, but data frame columns (and matrix columns) don't work with `vec_slice()` currently. One solution might be to call `vec_slice()` instead of `[` when you iterate over the columns of the data frame. I don't know if this greatly slows things down or not.

``` r
library(vctrs)
library(tibble)

x <- tibble(x = c(1,2), y = tibble(z = c(2, 5), y = c(3, 4)))
x
#> # A tibble: 2 x 2
#>       x   y$z    $y
#>   <dbl> <dbl> <dbl>
#> 1     1     2     3
#> 2     2     5     4

res <- vec_slice(x, 1L)
res
#> # A tibble: 1 x 2
#>       x   y$z
#>   <dbl> <dbl>
#> 1     1     2

str(res)
#> Classes 'tbl_df', 'tbl' and 'data.frame':    1 obs. of  2 variables:
#>  $ x: num 1
#>  $ y:Classes 'tbl_df', 'tbl' and 'data.frame':   2 obs. of  1 variable:
#>   ..$ z: num  2 5

vec_slice2 <- function (x, i) {
  if (is.logical(i)) {
    i <- which(i)
  }
  stopifnot(is.integer(i) || is.character(i))
  if (is.null(x)) {
    NULL
  }
  else if (is.data.frame(x)) {
    out <- lapply(x, vec_slice, i)
    #out <- lapply(x, `[`, i)
    vec_restore(out, x)
  }
  else if (is_vector(x)) {
    d <- vec_dims(x)
    if (d == 1) {
      if (is.object(x)) {
        x[i]
      }
      else {
        x[i, drop = FALSE]
      }
    }
    else if (d == 2) {
      x[i, , drop = FALSE]
    }
    else {
      miss_args <- rep(list(missing_arg()), d - 1)
      eval_bare(expr(x[i, !!!miss_args, drop = FALSE]))
    }
  }
  else {
    stop("`x` must be a vector", call. = FALSE)
  }
}

vec_slice2(x, 1L)
#> # A tibble: 1 x 2
#>       x   y$z    $y
#>   <dbl> <dbl> <dbl>
#> 1     1     2     3
```

